const {avg,med,pct}=require('./harness.js');const name=process.argv[2]||'base';const R=require(require('path').join(require('os').tmpdir(),`long_${name}_60x144.json`));const N=R.length,W=R[0].wk.length;
const f=(x,d=0)=>x==null?'-':x.toFixed(d);
console.log('== first events (week: p10/med/p90, n)');
for(const k of ['mainOffer','mainTry','gE','death','dgClear']){const a=R.map(m=>m.first[k]).filter(x=>x!=null);console.log(k.padEnd(10),pct(a,.1),med(a),pct(a,.9),'n='+a.length);}
console.log('\n== time series (12w)  gold(avg/med) fame trust pop E% advs lvAvg lvMax board posted/w town quest reqOpen reqDone');
for(let w=11;w<W;w+=12){const X=R.map(m=>m.wk[w]);const pw=avg(R.map(m=>avg(m.wk.slice(w-11,w+1).map(x=>x.posted))));
 console.log(String(w+1).padStart(3),f(avg(X.map(x=>x.gold))).padStart(6),f(med(X.map(x=>x.gold))).padStart(6),f(avg(X.map(x=>x.fame))).padStart(4),f(avg(X.map(x=>x.trust))).padStart(4),f(avg(X.map(x=>x.pop))).padStart(5),f(100*avg(X.map(x=>x.grade>=1?1:0))).padStart(4),f(avg(X.map(x=>x.n)),1).padStart(5),f(avg(X.map(x=>x.lvAvg)),1).padStart(5),f(avg(X.map(x=>x.lvMax)),1).padStart(5),f(avg(X.map(x=>x.board)),1).padStart(5),f(pw,2).padStart(5),f(avg(X.map(x=>x.town)),1).padStart(5),f(avg(X.map(x=>x.quest)),1).padStart(5),f(avg(X.map(x=>x.reqOpen)),1).padStart(4),f(avg(X.map(x=>x.reqDone)),1).padStart(5));}
console.log('\n== ledger per month by quarter');
const keys=['subsidy','fee','meal','tavern','reqIn','resale','consign','shop','matBuy','scout','cpay','csup','gift','order','other','build','net'];
console.log('Q   '+keys.map(k=>k.padStart(7)).join(''));
for(let q=0;q<W/12;q++){const row=keys.map(k=>avg(R.map(m=>avg(m.hist.slice(q*3,q*3+3).map(h=>h[k]||0)))));console.log(String(q+1).padStart(3)+' '+row.map(v=>f(v).padStart(7)).join(''));}
console.log('\n== returns by 12w window: n/game, succ%, combat share, combat succ, noncombat succ, late/all, party avg, rq n, rq succ, gradeE share, down/game');
for(let q=0;q<W/12;q++){const A=[].concat(...R.map(m=>m.ret.filter(x=>x.w>=q*12&&x.w<q*12+12)));const B=A.filter(x=>!x.rq&&!x.dg),C=B.filter(x=>x.c),NC=B.filter(x=>!x.c),RQ=A.filter(x=>x.rq),s=a=>a.length?100*a.filter(x=>x.ok).length/a.length:null;
 console.log(String(q+1).padStart(3),f(B.length/N,1).padStart(5),f(s(B),1).padStart(5),f(100*C.length/B.length).padStart(4),f(s(C),1).padStart(5),f(s(NC),1).padStart(5),f(100*B.filter(x=>x.late).length/B.length,1).padStart(5),f(avg(B.map(x=>x.n)),2).padStart(5),f(RQ.length/N,1).padStart(5),f(s(RQ),1).padStart(5),f(100*B.filter(x=>x.g>=1).length/B.length).padStart(4),f(A.reduce((t,x)=>t+x.down,0)/N,1).padStart(5),'pm2+',f(100*C.filter(x=>x.pm>1).length/Math.max(1,C.length)).padStart(3));}
console.log('\n== adventurer-weeks share by state/idle reason per 12w window (%)');
const IK=['_q','mates','noq','rest','fee','sleep','rain','req','_inj','_away','?','_etc'];console.log('Q   '+IK.map(k=>k.padStart(6)).join(''));
for(let q=0;q<W/12;q++){const T={};let n=0;for(const m of R)for(const x of m.wk.slice(q*12,q*12+12))for(const k in x.idle){T[k]=(T[k]||0)+x.idle[k];n+=x.idle[k];}console.log(String(q+1).padStart(3)+' '+IK.map(k=>f(100*(T[k]||0)/n,1).padStart(6)).join(''));}
console.log('\n== equity by join rank at week 48/96/144: lv(avg) done(avg)');
for(const w of [48,96,144]){const rows=[];for(let r=0;r<12;r++){const A=R.map(m=>{const L=m.snap[w].adv.filter(a=>a.alive).sort((a,b)=>a.j-b.j||a.id-b.id);return L[r];}).filter(Boolean);if(A.length<N*0.3)continue;rows.push(`#${r+1}:Lv${f(avg(A.map(a=>a.lv)),1)}/${f(avg(A.map(a=>a.done)),0)}건/j${f(avg(A.map(a=>a.j)),0)}`);}console.log('w'+w,rows.join('  '));}
console.log('\n== grade mix of adventurers & wallets & gear at 48/96/144');
for(const w of [48,96,144]){const A=[].concat(...R.map(m=>m.snap[w].adv.filter(a=>a.alive)));console.log('w'+w,'F',f(100*A.filter(a=>a.gr===0).length/A.length),'E',f(100*A.filter(a=>a.gr===1).length/A.length),'D',f(100*A.filter(a=>a.gr>=2).length/A.length),'wallet avg',f(avg(A.map(a=>a.wallet))),'med',f(med(A.map(a=>a.wallet))),'gear pieces avg',f(avg(A.map(a=>a.eqN)),2),'attach avg',f(avg(A.map(a=>a.att))),'home%',f(100*A.filter(a=>a.home).length/A.length),'save KB',f(avg(R.map(m=>m.snap[w].save))/1024),'mats',f(avg(R.map(m=>m.snap[w].mats))));}
console.log('\n== end',JSON.stringify({dishes:avg(R.map(m=>m.end.dishes)),mons:avg(R.map(m=>m.end.mons)),mats:avg(R.map(m=>m.end.mats)),req:avg(R.map(m=>m.end.reqDone)),tries:avg(R.map(m=>m.end.tries)),dead:avg(R.map(m=>m.stats.deaths)),inj:avg(R.map(m=>m.stats.injuries)),decoN:avg(R.map(m=>m.end.deco.filter(x=>x!=='table').length)),up:avg(R.map(m=>m.end.up.length)),dgClear:R.filter(m=>m.end.dg&&m.end.dg.clear).length}));
